const vectors=[['VEC-DIGITAL','Digitalisation'],['VEC-AIDATA','AI & Data'],['VEC-CUSTOMER','Customer'],['VEC-OPEX','Operational Excellence'],['VEC-SUSTAIN','Sustainability'],['VEC-LEAD','Leadership']].map(([id,name])=>({id,name,description:`Strategic capability demand for ${name}.`,horizon:'2026-2029',priority:'accelerate',skillIds:[],status:'approved'}));
const seed={schemaVersion:2,revision:1,updatedAt:new Date().toISOString(),domains:[{id:'DOM-DT',name:'Digital & Technology',description:'Digital products, data and technology capabilities.',status:'approved'},{id:'DOM-PC',name:'People & Culture',description:'Organisation, talent and people leadership capabilities.',status:'approved'}],groups:[{id:'GRP-DA',domainId:'DOM-DT',name:'Data & Analytics',description:'Data products, insight and decision support.',status:'approved'},{id:'GRP-SBO',domainId:'DOM-PC',name:'Skill-based Organisation',description:'Skill architecture and workforce activation.',status:'approved'}],skills:[],jobDescriptions:[],mappings:[],profiles:[],strategicVectors:vectors,agentRuns:[],interviews:[],reviewQueue:[],kfla:names.map((name,index)=>({id:`KFLA-${String(index+1).padStart(2,'0')}`,number:index+1,name,factor:factor(index+1),enabled:true,definition:'',source:'public-name'}))};
function migrate(value){const w=value||seed;return{...seed,...w,schemaVersion:2,jobDescriptions:Array.isArray(w.jobDescriptions)?w.jobDescriptions:[],mappings:Array.isArray(w.mappings)?w.mappings:[],strategicVectors:Array.isArray(w.strategicVectors)&&w.strategicVectors.length?w.strategicVectors:vectors,agentRuns:Array.isArray(w.agentRuns)?w.agentRuns:[],reviewQueue:Array.isArray(w.reviewQueue)?w.reviewQueue:[]};}
let workspace=migrate(store.workspace);
if($json.mode==='skill.read'){store.workspace=workspace;return[{json:{ok:true,workspace,message:'Skill workspace loaded from the active governed agent.'}}];}
if($json.mode==='skill.save'){const candidate=$json.body.workspace;if(!candidate||![1,2].includes(candidate.schemaVersion)||!Array.isArray(candidate.skills)||!Array.isArray(candidate.kfla))return[{json:{ok:false,statusCode:400,error:'Invalid Skill Designer workspace.'}}];workspace=migrate(candidate);workspace.revision=Number(workspace.revision||0)+1;workspace.updatedAt=new Date().toISOString();store.workspace=workspace;return[{json:{ok:true,workspace,message:`Skill workspace revision ${workspace.revision} persisted.`}}];}
if($json.mode==='skill.regression'){workspace=migrate($json.body.workspace||workspace);const findings=[];for(const skill of workspace.skills){const syntax=skill.syntax||{};if(!String(syntax.action||'').trim()||!String(syntax.object||'').trim())findings.push(`${skill.name}: Action + Object syntax incomplete`);if(!String(skill.observability||'').trim())findings.push(`${skill.name}: observable evidence missing`);}for(const job of workspace.jobDescriptions){const count=workspace.mappings.filter(item=>item.jobDescriptionId===job.id&&item.status!=='rejected').length;if(count>10)findings.push(`${job.title}: ${count} mapped skills exceeds the pilot maximum`);}return[{json:{ok:true,workspace,message:findings.length?`${findings.length} regression findings require review.`:'Taxonomy regression passed.',findings}}];}
workspace=migrate($json.workspaceCandidate||workspace);const result=$json.agentResult||{};const now=Date.now();
if($json.mode==='skill.map_job'){const jobId=$json.body.jobDescriptionId;workspace.mappings=workspace.mappings.filter(item=>item.jobDescriptionId!==jobId||item.status==='approved');for(const [index,item] of (result.mapping_proposals||[]).entries()){const id=`MAP-${now}-${index+1}`;workspace.mappings.push({id,jobDescriptionId:jobId,skillId:item.skillId,targetLevel:item.targetLevel,weight:item.weight,critical:Boolean(item.critical),relevance:item.relevance,rationale:item.rationale,evidence:[item.evidence],strategicVectorIds:item.strategicVectorIds,source:'agent',status:'proposed'});workspace.reviewQueue.push({id:`REV-${id}`,entityId:id,title:`Review ${workspace.skills.find(s=>s.id===item.skillId)?.name||item.skillId} mapping`,type:'profile_change',summary:item.rationale,confidence:item.relevance,evidence:item.evidence,status:'pending',payload:{jobDescriptionId:jobId,skillId:item.skillId}});}if(result.profile_proposal){const profileId=`PROFILE-${now}`;workspace.profiles.push({id:profileId,title:result.profile_proposal.title||'Draft skill profile',purpose:result.profile_proposal.purpose||'',jobFamily:'Pilot role',jobDescriptionId:jobId,skills:(result.mapping_proposals||[]).map(item=>({skillId:item.skillId,targetLevel:item.targetLevel,weight:item.weight,critical:Boolean(item.critical)})),status:'draft',version:1});workspace.reviewQueue.push({id:`REV-${profileId}`,entityId:profileId,title:`Review ${result.profile_proposal.title||'skill profile'}`,type:'profile_change',summary:'Agent-composed role profile awaiting accountable approval.',confidence:Number(result.confidence||70),evidence:'Grounded in the selected job description and approved catalog.',status:'pending'});}}
if($json.mode==='skill.ingest'){for(const [index,item] of (result.new_skill_proposals||[]).entries()){const id=`SK-${now}-${index+1}`;workspace.skills.push({id,name:item.name||`${item.action} ${item.object}`,description:item.definition,groupId:'GRP-SBO',dimension:item.dimension||'technical',aliases:[],observability:item.observability,futureRelevance:'core',status:'draft',version:1,syntax:{action:item.action,object:item.object,outcome:item.outcome}});workspace.reviewQueue.push({id:`REV-${id}`,entityId:id,title:item.name||`${item.action} ${item.object}`,type:'new_skill',summary:item.definition,confidence:Number(item.confidence||70),evidence:item.evidence,status:'pending'});}}
if($json.mode==='skill.interview'){const body=$json.body;let interview=workspace.interviews.find(item=>item.id===body.interviewId);if(!interview){interview={id:`INT-${now}`,roleTitle:String(body.roleTitle||'Untitled role'),stakeholder:String(body.stakeholder||'Manager'),interviewee:String(body.interviewee||''),status:'in_progress',currentQuestion:0,responses:[]};workspace.interviews.push(interview);}if(String(body.answer||'').trim())interview.responses.push({question:interview.nextQuestion||'Describe an observable critical incident.',answer:String(body.answer)});interview.currentQuestion=Math.min(6,interview.currentQuestion+1);interview.nextQuestion=String(result.next_question||'What distinguishes strong from exceptional performance in this role?');if(interview.currentQuestion>=6)interview.status='complete';}
workspace.agentRuns=[...($json.agentRun?[$json.agentRun]:[]),...workspace.agentRuns].slice(0,100);workspace.revision=Number(workspace.revision||0)+1;workspace.updatedAt=new Date().toISOString();store.workspace=workspace;const proposalCount=(result.mapping_proposals||[]).length+(result.new_skill_proposals||[]).length;return[{json:{ok:true,workspace,agentRun:$json.agentRun,proposals:workspace.reviewQueue.filter(item=>item.status==='pending'),message:$json.mode==='skill.map_job'?'AI mapping draft added to human review.':$json.mode==='skill.interview'?'Agent-guided interview progress saved.':`${proposalCount} governed proposals added to review.`}}];
